<?php
declare(strict_types=1);

use FMonitor2\YiiRuntime\Assets\ShellAssetBundle;
use FMonitor2\YiiRuntime\MainNavigation;
use yii\helpers\Html;

ShellAssetBundle::register($this);
$initials='';foreach(array_slice(preg_split('/\s+/u',trim($identity->displayName),-1,PREG_SPLIT_NO_EMPTY)?:[],0,2)as$part)$initials.=mb_strtoupper(mb_substr($part,0,1));
$csrf=Html::hiddenInput(Yii::$app->request->csrfParam,Yii::$app->request->csrfToken);
$byDate=[];foreach($events as$event)$byDate[$event['type']][$event['date']][]=$event;
$calendarRows=['planned_start'=>['Плановое начало','accent'],'planned_end'=>['Плановое завершение','warning'],'inspection'=>['Инспекции','success']];
$eventMarkup=static function(array$event,string$tone):string{$schedule=$event['scheduleId']!==null?' data-schedule-id="'.(int)$event['scheduleId'].'"':'';return'<li class="shlz-calendar-grid__item" data-tone="'.Html::encode($tone).'"'.$schedule.' data-object-id="'.(int)$event['objectId'].'" data-event-type="'.Html::encode($event['type']).'"><a class="fm2-calendar-event-link" href="/pilot/objects/'.(int)$event['objectId'].'"><strong>'.Html::encode($event['registration']!==''?$event['registration']:'Объект № '.$event['objectId']).'</strong><span>'.Html::encode($event['address']).'</span></a></li>';};
$days=[];for($day=$first;$day<=$last;$day=$day->modify('+1 day'))$days[]=$day;
$todayIso=$today->format('Y-m-d');$selectedIso=$selected->format('Y-m-d');
$groups=[];foreach($days as$day){$iso=$day->format('Y-m-d');$state=$iso===$todayIso?'today':($iso<$todayIso?'past':'future');$groups[$state]=($groups[$state]??0)+1;}
$week=['1'=>'Пн','2'=>'Вт','3'=>'Ср','4'=>'Чт','5'=>'Пт','6'=>'Сб','7'=>'Вс'];
$this->beginPage();
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Календарь работ · FMonitor 2.0</title><link rel="icon" href="/pilot/assets/favicon.svg"><?php $this->head()?></head><body class="shlz-scope"><?php $this->beginBody()?>
<a class="fm2-skip shlz-link" href="#main-content">Перейти к содержанию</a>
<div class="fm2-shell"><aside class="fm2-sidebar"><div class="fm2-nav-body"><a class="fm2-logo" href="/pilot/objects"><svg class="fm2-logo-mark" viewBox="0 0 32 32" aria-hidden="true"><rect class="fm2-logo-rail" x="5" y="4" width="4" height="24"/><rect class="fm2-logo-rail" x="23" y="4" width="4" height="24"/><rect class="fm2-logo-progress" x="11" y="10" width="10" height="12"/></svg><span class="fm2-logo-name">FMonitor 2.0</span></a><?=MainNavigation::render($identity,'calendar')?></div>
<div class="fm2-sidebar-user"><span class="shlz-avatar shlz-avatar--32 fm2-sidebar-avatar"><?=Html::encode($initials)?></span><span class="fm2-sidebar-user-copy"><strong><?=Html::encode($identity->displayName)?></strong><small><?=Html::encode($identity->email)?></small></span><form method="post" action="/pilot/logout" class="fm2-logout-form"><?=$csrf?><button class="fm2-logout" type="submit" aria-label="Выйти"><svg class="fm2-user-logout-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M10 4H5v16h5M14 8l4 4-4 4m4-4H9" fill="none" stroke="currentColor" stroke-width="1.7"/></svg><span class="fm2-logout-text">Выйти</span></button></form></div><?=MainNavigation::collapseControl()?></aside>
<div class="fm2-workspace"><main class="fm2-main" id="main-content" tabindex="-1"><section class="fm2-calendar-page" data-calendar-page><header class="fm2-calendar-header"><div><h1>Календарь работ</h1><p>Запланированные инспекции объектов монтажа</p></div><span class="fm2-result-count"><?=count($events)?> событий</span></header>
<div class="fm2-calendar-toolbar" aria-label="Навигация по календарю"><div class="fm2-calendar-period"><h2>Непрерывная шкала дат</h2><span><?=Html::encode($first->format('d.m.Y').' — '.$last->format('d.m.Y'))?></span></div><a class="shlz-button" href="/pilot/calendar">Сегодня</a></div>
<div class="fm2-calendar-layout"><div class="shlz-calendar-grid fm2-calendar-grid" data-shlz-calendar-grid><table><caption class="fm2-visually-hidden">События объектов с <?=Html::encode($first->format('d.m.Y'))?> по <?=Html::encode($last->format('d.m.Y'))?></caption><thead><tr><th scope="col" rowspan="2">Тип события</th><?php foreach(['past'=>'Прошлое','today'=>'Сегодня','future'=>'Будущее']as$state=>$label):if(!isset($groups[$state]))continue?><th scope="colgroup" colspan="<?=$groups[$state]?>" data-shlz-calendar-grid-state="<?=$state?>"><span class="shlz-calendar-grid__group-label"><?=$label?></span></th><?php endforeach?></tr><tr data-shlz-calendar-grid-header-row="dates"><?php foreach($days as$day):$iso=$day->format('Y-m-d');$state=$iso===$todayIso?'today':($iso<$todayIso?'past':'future')?><th id="calendar-day-<?=$iso?>" scope="col" data-shlz-calendar-grid-state="<?=$state?>"><form method="get" action="/pilot/calendar"><button class="fm2-calendar-day<?=$iso===$selectedIso?' is-selected':''?>" type="submit" name="date" value="<?=$iso?>" data-calendar-date="<?=$iso?>" aria-pressed="<?=$iso===$selectedIso?'true':'false'?>"<?=$iso===$selectedIso?' autofocus':''?>><span class="shlz-calendar-grid__date-primary"><?=$day->format('j')?></span><span class="shlz-calendar-grid__date-secondary"><?=$week[$day->format('N')]?></span></button></form></th><?php endforeach?></tr></thead><tbody><?php foreach($calendarRows as$type=>[$rowLabel,$tone]):$rowEvents=$byDate[$type]??[]?><tr><th id="calendar-row-<?=$type?>" scope="row"><span><?=$rowLabel?></span><span class="shlz-calendar-grid__row-description"><?=array_sum(array_map('count',$rowEvents))?> событий</span></th><?php foreach($days as$day):$iso=$day->format('Y-m-d');$state=$iso===$todayIso?'today':($iso<$todayIso?'past':'future');$items=$rowEvents[$iso]??[]?><td headers="calendar-row-<?=$type?> calendar-day-<?=$iso?>" data-shlz-calendar-grid-state="<?=$state?>"><?php if($items===[]):?><span class="fm2-calendar-cell-empty" aria-label="Нет событий">—</span><?php else:$visible=array_slice($items,0,2);$hidden=array_slice($items,2);$moreId='calendar-more-'.$type.'-'.$iso?><ul class="shlz-calendar-grid__items"><?php foreach($visible as$event):?><?=$eventMarkup($event,$tone)?><?php endforeach?><?php if($hidden!==[]):?><li><button class="shlz-button shlz-button--sm shlz-calendar-grid__disclosure" type="button" data-shlz-calendar-grid-disclosure="cell" aria-controls="<?=$moreId?>" aria-expanded="false">Ещё <?=count($hidden)?></button><ul class="shlz-calendar-grid__items" id="<?=$moreId?>" hidden><?php foreach($hidden as$event):?><?=$eventMarkup($event,$tone)?><?php endforeach?></ul></li><?php endif?></ul><?php endif?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div>
<?php $agenda=[];foreach($calendarRows as $type=>[$rowLabel,$tone])foreach($byDate[$type][$selectedIso]??[] as $event)$agenda[]=$event+['rowLabel'=>$rowLabel,'tone'=>$tone]?><aside class="fm2-calendar-agenda" aria-labelledby="calendar-agenda-title" aria-live="polite"><header><div><h2 id="calendar-agenda-title"><?=$selected->format('d.m.Y')?></h2><p><?=count($agenda)?> событий</p></div></header><div data-calendar-agenda><?php if($agenda===[]):?><p class="fm2-calendar-empty">На этот день событий нет.</p><?php else:?><ul class="fm2-agenda-list"><?php foreach($agenda as$event):$objectLabel=$event['address']!==''?$event['address'].($event['entrance']!==''?', подъезд '.$event['entrance']:''):'Карточка объекта № '.$event['objectId']?><li class="fm2-agenda-item"<?=$event['scheduleId']!==null?' data-schedule-id="'.(int)$event['scheduleId'].'"':''?> data-object-id="<?=$event['objectId']?>" data-event-type="<?=$event['type']?>"><span class="fm2-agenda-tone" data-tone="<?=$event['tone']?>" aria-hidden="true"></span><div><strong><?=Html::encode($event['rowLabel'])?></strong><a class="shlz-link" href="/pilot/objects/<?=$event['objectId']?>"><?=Html::encode($objectLabel)?></a><span><?=Html::encode($event['registration']!==''?'Рег. № '.$event['registration']:'Объект № '.$event['objectId'])?> · <?=Html::encode($event['rowLabel'])?></span></div></li><?php endforeach?></ul><?php endif?></div></aside></div></section></main></div></div>
<?php $this->endBody()?></body></html><?php $this->endPage()?>
